INSERT INTO feature VALUES('univalence-axiom','identity','Univalence on a record''s laws (ua)',NULL,'partial','uncommon','dependent provers','`ua(e)` makes a bi-invertible record `e : A ≃ B` a path `Path[.A = Type](A, B)` at any two codes, admitted on its laws as typed evidence; transport along it applies the record''s map by conversion; `ua ∘ idtoequiv` and `idtoequiv ∘ ua` are owed until #520 proves them. Transport along ua(e) runs in the machine (#708): the path lowered to its two-map record, the motive by shape (identity, constant, product, sum, list); transport back along `ua(e)` applies the record''s left inverse, and along `Path.step(p, ua(e))` moves along `p`, then the forward map, and a function moves along `ua(e)` by the record''s maps, its argument back by the left inverse and its result forward, in both checkers, and the machine runs each: the motive by shape (identity, constant, product, sum, list, a pure function, a path between types moving at an endpoint), a transport along `Path.back` or `Path.step` running the transport that computes it first.','kernel-term kernel-core core-term core-nbe core-checker core-sequent surface-lowering','corpus/model/identity/univalence.gandr corpus/pathological/identity/univalence.gandr corpus/model/identity/univalence-back.gandr corpus/model/identity/univalence-then.gandr corpus/model/identity/univalence-function.gandr corpus/model/identity/transport-path.gandr corpus/model/identity/univalence-transports.gandr corpus/model/identity/certificate-transport.gandr','corpus/ledger/features/univalence-axiom.gandr','#312 #520');
